  "id": "bandit-b113-request-without-timeout",
  "revision": 1,
  "mode": "steer",
  "description": "Pass a timeout to every HTTP call made with requests.",
  "scope": {
    "include": [
      "**/*.py"
    ]
  },
  "clauses": [
    {
      "id": "call",
      "forbid": {
        "ast": {
          "language": "python",
          "rule": {
            "pattern": "requests.get($URL)"
          }
        }
      },
      "violation": {
        "code": "NO_TIMEOUT",
        "anchor": "witness.span",
        "message": "Bandit B113 (request_without_timeout)"
      }
    }
  ]
}

